// CSD_RATIONALE_BEGIN
// Root cause of the 40.8% ceiling: the best attempt used `next == "<<"` for
// span-entry detection, which NEVER matched for Qwen's tokenizer (space-prefixed
// " <<"). Result: 0/49 examples engaged the constrained branch, leaving every
// span content unconstrained and open to {template} variable syntax, Python `//`
// floor division, and `if/else` inline conditionals — the exact 3 syntax failures.
//
// Fix: replace exact token equality with `RenderedEndsWith(generated, "<<")`.
// This fires correctly for any token rendering that ends with "<<" (space-prefix,
// split delimiter, etc.) and makes the constrained branch engage for every span.
//
// Inside spans: AdaptiveConstrainedStep hard-masks to parser-valid tokens
// (blocking `{`, `}`, Python-specific syntax) while its conditional group soft-
// boosts at narrow parser states leave the LM's natural distribution for normal
// arithmetic largely intact. CloseConstrainedSpan fires only when IsCompletePrefix
// to prevent premature closure. CloseSpanWithinBudget handles cleanup when the
// remaining budget is ≤ 3 steps.
//
// Improved guidance: explicitly discourages {variable} template syntax, Python
// // floor division, and if/else inline expressions inside << >>.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//    Initialization: set from precondition (insideConstrained ==> IsValidPrefix(currentConstrained)).
//    EnterObservedConstrainedSpan branch: sets currentConstrainedOut := []; the
//      method precondition requires parser.IsValidPrefix([]), so the invariant holds.
//    CloseConstrainedSpan branch: sets insideConstrainedOut := false, making the
//      implication vacuously true; also resets currentConstrainedOut := [].
//    CloseSpanWithinBudget branch: its postcondition directly guarantees
//      insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//    AdaptiveConstrainedStep + AppendConstrainedToken branch: AdaptiveConstrainedStep
//      returns EOS or a token t for which IsTokenValidNext holds at currentConstrainedOut;
//      AppendConstrainedToken extends currentConstrainedOut by t, preserving IsValidPrefix
//      by the definition of a parser-valid extension.
//    EOS break: span state unchanged, invariant trivially preserved.
//
// 2. progress: |generated| <= |generatedPrefix| + steps
//    Initialization: steps=0, generated=generatedPrefix; equality holds.
//    Unconstrained branch: steps += 1, generated grows by at most 1 token (EOS
//      breaks without appending). |generated_new| <= |generatedPrefix| + steps_new. ✓
//    CloseConstrainedSpan branch: steps += 1, generated grows by at most 1 token
//      (the ">>" delimiter). |generated_new| <= |generatedPrefix| + steps_new. ✓
//    CloseSpanWithinBudget branch: closeBudget = maxSteps - steps ≥ 1 since
//      steps < maxSteps. Postcondition gives |cg| <= |generated| + closeBudget.
//      After steps := maxSteps: |generated| <= |generatedPrefix| + steps_old +
//      (maxSteps - steps_old) = |generatedPrefix| + maxSteps = |generatedPrefix| + steps_new. ✓
//    AdaptiveConstrainedStep + AppendConstrainedToken branch: steps += 1,
//      AppendConstrainedToken appends exactly 1 token to generated.
//      |generated_new| = |generated_old| + 1 <= |generatedPrefix| + steps_new. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap each intermediate computation and the final answer in << >> delimiters. Write variable names exactly as they appear in the problem WITHOUT curly braces {}. Use only standard arithmetic operators: +, -, *, /, ** for exponentiation. Do NOT write Python if/else expressions inside << >> spans, and do NOT use // for floor division. Keep each << >> expression as a single simple arithmetic expression.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
    }
  } else {
    // Inside a constrained span
    if parser.IsCompletePrefix(currentConstrainedOut) {
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

